history['entries'].insert(0,{'version':'0.85.3','date':'2026-10-16','title':'Ready-to-use planting presets.','era':'recent','legacy':False,'note':'Scoped Max 2027 development delivery; normal artist installation and production-renderer acceptance remain separate.','changes':[{'kind':'Added','text':'Eight ready presets supply models, materials, evaluated terrain, spline context and complete Paint. Load + Update adds new layers.'},{'kind':'Improved','text':'Ready Save captures exact dependencies; renamed presets retain their assets and Undo/Redo restores complete publications.'},{'kind':'Fixed','text':'Required channel data can use included terrain; delayed notifications no longer cause a redundant Live load solve. Nested package paths support Windows long-path handling.'}],'evidence':['docs/plans/preset-gallery-improvements/LOAD_0853.md']})
