manifest=json.loads((site/'content/source-manifest.json').read_text());allowed={'docs/ARTIST_GUIDE.md','docs/Release_Versioning.md','docs/ARCHITECTURE.md','docs/Current_System_2026-10-05/CAPABILITY_MATRIX.md','docs/plans/preset-gallery-improvements/ARTIST_WORKFLOW.md','docs/plans/preset-gallery-improvements/LOAD_0853.md'}
